#!/usr/bin/env python3
"""Exact integer acceptance; floating point LP proposes duals and splits only.
Usage: python verify.py [72_4.txt [threads]]
Download from https://users.aalto.fi/~pat/opt/72_4.txt if passing a local first argument.
"""
import hashlib, os, pathlib, subprocess, sys, tempfile, urllib.request
from collections import Counter, defaultdict
def run():
    assert __debug__, "run this verifier without -O"
    raw = pathlib.Path(sys.argv[1]).read_bytes() if len(sys.argv)>1 else urllib.request.urlopen("https://users.aalto.fi/~pat/opt/72_4.txt").read()
    z = list(map(int, raw.split()))
    assert len(z)==7010 and z[:2]==[96,11]
    normalized=''.join(str(x)+'\n' for x in z).encode()
    assert hashlib.sha256(normalized).hexdigest()=='0f3fe74e631f11d3d3263c1c476d86ad142298ed6e2184f2b06370c771519d23'
    C=[z[3+i*73:75+i*73] for i in range(96)]
    assert all(z[2+i*73]==72 and len(set(c))==72 and all(0<=u<2048 for u in c) and min((u^v).bit_count() for u in c for v in c if u!=v)==4 for i,c in enumerate(C))
    data=''.join(' '.join(map(str,c))+'\n' for c in C)
    with tempfile.TemporaryDirectory() as base:
        wd=pathlib.Path(base)
        (wd/'C.dat').write_text(data)
        for name, source in SOURCES.items(): (wd/name).write_text(source)
        env=dict(os.environ,OMP_NUM_THREADS=sys.argv[2] if len(sys.argv)>2 else '2')
        for exe in ['gate','hole','rad']:
            subprocess.run([os.environ.get('CXX','c++'),'-std=c++17','-O3','-fopenmp',exe+'.cpp','-o',exe],cwd=wd,check=True)
            subprocess.run([str(wd/exe)],cwd=wd,env=env,check=True)
        groups=defaultdict(list)
        for s in (wd/'holes.tsv').read_text().splitlines():
            i,j,v,result,*_=map(int,s.split())
            assert result!=0
            if result==1:
                assert j>=0 and all((x^v).bit_count()>=4 for k,x in enumerate(C[i]) if k!=j)
                groups[i,j].append(v)
        assert Counter(map(len,groups.values()))=={1:6396,2:324,3:160,12:32} and len(groups)==96*72
        for i in range(96):
            for j in range(72):
                true={v for v in range(2048) if all((c^v).bit_count()>=4 for k,c in enumerate(C[i]) if k!=j)}
                assert true==set(groups[i,j])
        rows=[list(map(int,s.split()))[:7] for s in (wd/'rad.tsv').read_text().splitlines()]
        tasks={(i,j,v,2047^(v^w),4-(v^w).bit_count()) for (i,j),vs in groups.items() for v in vs for w in vs}
        assert len(rows)==len(tasks)==13740 and all(tuple(row[:5]) in tasks and row[5]==-1 for row in rows)
        assert {tuple(row[:5]) for row in rows}==tasks
        print('All 6,912 one-to-two continuous trades excluded; 6,396 single-corner cases.')
SOURCES={"lp.h":"struct LP{int m,n;vector<int>B,N;vector<vector<double>>D;LP(vector<vector<double>>A,vector<double>b,vector<double>c):m(b.size()),n(c.size()),B(m),N(n+1),D(m+2,vector<double>(n+2)){for(int i=0;i<m;i++)for(int j=0;j<n;j++)D[i][j]=A[i][j];for(int i=0;i<m;i++)B[i]=n+i,D[i][n]=-1,D[i][n+1]=b[i];for(int j=0;j<n;j++)N[j]=j,D[m][j]=-c[j];N[n]=-1;D[m+1][n]=1;}void pivot(int r,int s){double inv=1/D[r][s];for(int i=0;i<m+2;i++)if(i!=r&&abs(D[i][s])>1e-14){double q=D[i][s]*inv;for(int j=0;j<n+2;j++)if(j!=s)D[i][j]-=D[r][j]*q;D[i][s]*=-inv;}for(int j=0;j<n+2;j++)if(j!=s)D[r][j]*=inv;D[r][s]=inv;swap(B[r],N[s]);}bool sp(int ph){int r0=ph==1?m+1:m;for(int lim=0;lim<2000;lim++){int s=-1;for(int j=0;j<=n;j++){if(ph==2&&N[j]==-1)continue;if(s<0||make_pair(D[r0][j],N[j])<make_pair(D[r0][s],N[s]))s=j;}if(D[r0][s]>-1e-8)return true;int r=-1;for(int i=0;i<m;i++)if(D[i][s]>1e-8){if(r<0||make_pair(D[i][n+1]/D[i][s],B[i])<make_pair(D[r][n+1]/D[r][s],B[r]))r=i;}if(r<0)return false;pivot(r,s);}return false;}double solve(vector<double>&y){int r=0;for(int i=0;i<m;i++)if(D[i][n+1]<D[r][n+1])r=i;if(D[r][n+1]<-1e-8){pivot(r,n);if(!sp(1)||D[m+1][n+1]<-1e-8)return -1e30;for(int i=0;i<m;i++)if(B[i]==-1){int s=0;for(int j=1;j<=n;j++)if(abs(D[i][j])>abs(D[i][s]))s=j;if(abs(D[i][s])>1e-8)pivot(i,s);}}if(!sp(2))return 1e30;y.assign(m,0);for(int j=0;j<=n;j++)if(N[j]>=n)y[N[j]-n]=D[m][j];return D[m][n+1];}};","gate.cpp":"#include <bits/stdc++.h>\n#include <omp.h>\nusing namespace std;\n#include \"lp.h\"\nint W[2048];\nstruct R{int up;vector<int> supp;int n,m;bool ex;};\nR bound(const vector<int>&C,int v,int d){vector<vector<double>>A;vector<double>b;vector<int>idx;for(int i=0;i<72;i++)if(i!=d){int s=C[i]^v;vector<double>row(12);for(int j=0;j<11;j++)row[j]=(s>>j&1)?3:-1;row[11]=1;A.push_back(row);b.push_back(4*W[s]);idx.push_back(i);}for(int j=0;j<11;j++){vector<double>row(12);row[j]=1;A.push_back(row);b.push_back(1);}vector<double>O(12),Y;O[11]=1;LP lp(A,b,O);double z=lp.solve(Y);vector<int>supp;long long P[11]={};long long T=0,tot=0;for(int i=0;i<(int)idx.size()&&i<(int)Y.size();i++){int q=isfinite(Y[i])?int(llround(clamp(Y[i]*1048576.,0.,16777216.))):0;if(q){int s=C[idx[i]]^v;T+=q;tot+=4LL*W[s]*q;supp.push_back(idx[i]);for(int j=0;j<11;j++)P[j]+=q*((s>>j&1)?-3:1);}}for(long long q:P)tot+=max(0LL,q);bool ex=T>0&&tot<16*T;return {(isfinite(z)?(int)llround(clamp(1000*z,-1000000.,1000000.)):0),supp,0,0,ex};}\nint main(){vector<vector<int>>C(96,vector<int>(72));ifstream F(\"C.dat\");for(auto&a:C)for(int&i:a)F>>i;for(int v=1;v<2048;v++)W[v]=W[v&(v-1)]+1;ofstream of(\"gates.tsv\");atomic<int>nn(0);long long nlp=0,tot=0;\n#pragma omp parallel for schedule(dynamic) reduction(+:nlp,tot)\nfor(int i=0;i<96;i++){ostringstream os;int n=0,other=0;for(int v=0;v<2048;v++){auto b=bound(C[i],v,-1);nlp++;vector<int>S=b.supp;if(!b.ex){S.resize(72);iota(S.begin(),S.end(),0);os<<i<<\" \"<<v<<\" -1 \"<<b.up<<'\\n';}for(int k:S){auto t=bound(C[i],v,k);nlp++;if(!t.ex){os<<i<<\" \"<<v<<\" \"<<k<<\" \"<<t.up<<'\\n';n++;if(v!=C[i][k])other++;}}}\n#pragma omp critical\n{of<<os.str();of.flush();int x=++nn;if(x%10==0)cerr<<\"LP \"<<x<<\"/96 \"<<n<<\" \"<<other<<\"\\n\";}tot+=n;}\ncout<<\"ALL gate survivors \"<<tot<<\" LP \"<<nlp<<\"\\n\";}","bx.h":"#include <bits/stdc++.h>\n#include <omp.h>\nusing namespace std;\n#include \"lp.h\"\nconst int Q=128,T0=16*Q*Q;\nint W[2048];vector<vector<int>>C(96,vector<int>(72));\nstruct Bx{array<int,11> l{},h;Bx(){h.fill(Q);}};\nstruct Row{array<int,11>A{};int b,id;};\nint exactMask(int v,int i,int j,const array<int,11>&y,int mask,int T){int m=INT_MAX;for(int c=0;c<72;c++)if(c!=j){int d=0;for(int k=0;k<11;k++){int e=((C[i][c]^v)>>k&1)?2*Q-y[k]:y[k];d+=e*e;}m=min(m,d);}if(mask>=0){int a=0;for(int k=0;k<11;k++)if(mask>>k&1)a+=y[k]*y[k];m=min(m,T0-T*Q*Q+a);}return m;}\nstruct Solver{long long calls=0,lpN=0,blimit=12000;int dep=85;array<int,11>hit{};int rec(int i,int j,int v,int mask,int T,Bx&x,int depth){if(++calls>blimit)return 0;vector<Row> rows;for(int c=0;c<72+(mask>=0);c++)if(c!=j){Row a;a.id=c;a.b=c==72?T0-T*Q*Q:0;for(int k=0;k<11;k++){if(c==72&&!(mask>>k&1))continue;int e=c==72?0:2*Q*((v^C[i][c])>>k&1);int l=x.l[k],h=x.h[k];a.b+=(l-e)*(l-e);a.A[k]=(l+h-2*e)*(h-l);}long long mn=a.b,mx=a.b;for(int d:a.A){mn+=min(d,0);mx+=max(d,0);}if(mx<T0)return -1;if(mn<T0)rows.push_back(a);}if(rows.empty()){hit=x.l;return 1;}vector<vector<double>> A;vector<double>b;for(auto&r:rows){vector<double> aa(12);for(int k=0;k<11;k++)aa[k]=-double(r.A[k])/Q/Q;aa[11]=1;A.push_back(aa);b.push_back(double(r.b)/Q/Q);}for(int k=0;k<11;k++){vector<double>aa(12);aa[k]=1;A.push_back(aa);b.push_back(1);}vector<double>o(12),y;o[11]=1;LP lp(A,b,o);lpN++;double z=lp.solve(y);vector<long long> g(11);long long tot=0,n=0;for(int r=0;r<(int)rows.size()&&r<(int)y.size();r++){int wt=isfinite(y[r])?int(llround(clamp(y[r]*65536.,0.,16777216.))):0;n+=wt;tot+=1LL*rows[r].b*wt;for(int k=0;k<11;k++)g[k]+=1LL*rows[r].A[k]*wt;}for(long long a:g)tot+=max(a,0LL);if(n&&tot<n*T0)return -1;array<int,11>point=x.l;for(int r=0;r<lp.m;r++)if(lp.B[r]<11&&lp.B[r]>=0){int k=lp.B[r];double t=lp.D[r][lp.n+1];if(isfinite(t))point[k]=x.l[k]+int(llround((x.h[k]-x.l[k])*clamp(t,0.,1.)));}\nif(exactMask(v,i,j,point,mask,T)>=T0){hit=point;return 1;}\nif(depth>=dep)return 0;double best=-1;int K=-1;\nfor(int k=0;k<11;k++){int l=x.l[k],h=x.h[k],w=h-l;if(w<2)continue;double g=(point[k]-l)*(h-point[k]);double sc=g+0.0001*w*w;if(sc>best)best=sc,K=k;}if(K<0)return 0;int l=x.l[K],h=x.h[K],mid=(l+h)/2;\nx.h[K]=mid;int a=rec(i,j,v,mask,T,x,depth+1);x.h[K]=h;if(a==1)return 1;x.l[K]=mid;int b2=rec(i,j,v,mask,T,x,depth+1);x.l[K]=l;return b2==1?1:(a<0&&b2<0?-1:0);}\n};","hole.cpp":"#include \"bx.h\"\nint main(){ifstream f(\"C.dat\");for(auto&a:C)for(int&i:a)f>>i;for(int v=1;v<2048;v++)W[v]=W[v&(v-1)]+1;ifstream g(\"gates.tsv\");vector<array<int,4>> E;int i,v,j,b;while(g>>i>>v>>j>>b)E.push_back({i,v,j,b});ofstream o(\"holes.tsv\");atomic<int> dn(0);long long box=0,lp=0;\n#pragma omp parallel for schedule(dynamic) reduction(+:box,lp)\nfor(int k=0;k<(int)E.size();k++){auto [i,v,j,b]=E[k];bool binary=true;for(int t=0;t<72;t++)if(t!=j&&W[C[i][t]^v]<4)binary=false;Solver s;Bx x;int a=binary?1:s.rec(i,j,v,-1,0,x,0);box+=s.calls;lp+=s.lpN;\n#pragma omp critical\n{o<<i<<\" \"<<j<<\" \"<<v<<\" \"<<a<<\" \"<<s.calls;for(int t:s.hit)o<<\" \"<<t;o<<\"\\n\";int z=++dn;if(z%2000==0)cerr<<\"holes \"<<z<<\"\\n\";}}\ncout<<\"real hole gates \"<<box<<\" \"<<lp<<\"\\n\";}","rad.cpp":"#include \"bx.h\"\nint main(){ifstream f(\"C.dat\");for(auto&a:C)for(int&i:a)f>>i;for(int v=1;v<2048;v++)W[v]=W[v&(v-1)]+1;map<pair<int,int>,vector<int>>H;ifstream g(\"holes.tsv\");string line;while(getline(g,line)){istringstream is(line);int i,j,v,a;is>>i>>j>>v>>a;if(a>0)H[{i,j}].push_back(v);}vector<array<int,5>>E;for(auto&[k,V]:H)for(int v:V)for(int w:V){int d=W[v^w],mask=2047^(v^w);E.push_back({k.first,k.second,v,mask,4-d});}sort(E.begin(),E.end());E.erase(unique(E.begin(),E.end()),E.end());ofstream o(\"rad.tsv\");long long box=0,lp=0,yes=0,unk=0;atomic<int>dn(0); \n#pragma omp parallel for schedule(dynamic) reduction(+:box,lp,yes,unk)\nfor(int k=0;k<(int)E.size();k++){auto[i,j,v,mask,T]=E[k];Solver s;s.blimit=4000;s.dep=55;Bx x;int a=s.rec(i,j,v,mask,T,x,0);box+=s.calls;lp+=s.lpN;yes+=a==1;unk+=a==0;\n#pragma omp critical\n{o<<i<<\" \"<<j<<\" \"<<v<<\" \"<<mask<<\" \"<<T<<\" \"<<a<<\" \"<<s.calls;for(int t:s.hit)o<<\" \"<<t;o<<\"\\n\";int z=++dn;if(z%2000==0)cerr<<\"rad \"<<z<<\"/\"<<E.size()<<\"\\n\";}}\ncout<<\"real rad cases=\"<<E.size()<<\" box=\"<<box<<\" lp=\"<<lp<<\" pass=\"<<yes<<\" unk=\"<<unk<<\"\\n\";}"}
if __name__=='__main__': run()
